command:example.dev:code:
try {
    Invoke-RestMethod -Uri 'https://api.example.com/items/42'
}
catch {
    $detail = Get-HttpErrorDetail -ErrorRecord $_
    if ($detail.StatusCode -eq 404) { return $null }
    throw "Request failed with $($detail.StatusCode): $($detail.Body)"
}

function Remove-Widget {
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)][string]$Name)
    $bound = $PSBoundParameters
    Invoke-TcsCommand -ScriptBlock {
        if ($PSCmdlet.ShouldProcess($Name, 'Remove widget')) {
            Invoke-RestMethod -Method Delete -Uri "https://api.example.com/widgets/$Name"
        }
        Write-Verbose "Parameters: $($bound.Keys -join ', ')"
    }
}

function Get-Widget {
    [CmdletBinding()]
    param([Parameter(ValueFromPipeline)][string]$Name)
    begin { $telemetry = Start-TcsTelemetry }
    process {
        Invoke-TcsCommand -Token $telemetry -ScriptBlock {
            Invoke-RestMethod -Uri "https://api.example.com/widgets/$Name"
        }
    }
    end { Complete-TcsTelemetry -Token $telemetry }
}

$id = [guid]::NewGuid().ToString()
Invoke-TelemetryCollection -ModuleName 'tcs.jira' -ModuleVersion '0.1.0' -CommandName 'Get-JiraTicket' -ExecutionID $id -Stage Start
try {
    # command body
    Invoke-TelemetryCollection -ModuleName 'tcs.jira' -ModuleVersion '0.1.0' -CommandName 'Get-JiraTicket' -ExecutionID $id -Stage End
}
catch {
    Invoke-TelemetryCollection -ModuleName 'tcs.jira' -ModuleVersion '0.1.0' -CommandName 'Get-JiraTicket' -ExecutionID $id -Stage End -Failed $true -Exception $_
    throw
}

# Create a parameter with custom validation script
$script = { $_ -match '^[A-Z]{2,3}$' }
$dynParam = New-DynamicParameter -Name "CountryCode" -ParameterType ([string]) -ValidateScript $script

function Get-Widget {
    [CmdletBinding()]
    param([Parameter(ValueFromPipeline)][string]$Name)
    begin {
        $telemetry = Start-TcsTelemetry
    }
    process {
        Invoke-TcsCommand -Token $telemetry -ScriptBlock {
            Get-Item -Path $Name
        }
    }
    end {
        Complete-TcsTelemetry -Token $telemetry
    }
}

begin { $telemetry = Start-TcsTelemetry }
process {
    try { Set-Thing -Name $Name -ErrorAction Stop }
    catch { Complete-TcsTelemetry -Token $telemetry -ErrorRecord $_; throw }
}
end { Complete-TcsTelemetry -Token $telemetry }
